import type { ArcRotateCamera, SceneContext } from "@babylonjs/lite";
import { interpolateArcRotateCamera } from "@babylonjs/lite";

const TWO_PI = Math.PI * 2;

export async function spinAround(
  camera: ArcRotateCamera,
  scene: SceneContext,
  turns: number,
): Promise<void> {
  if (!Number.isFinite(turns) || turns === 0) {
    return;
  }

  const startAlpha = camera.alpha;
  const targetAlpha = startAlpha + TWO_PI * turns;

  // Animate only alpha so radius, beta, and target stay unchanged.
  await interpolateArcRotateCamera(camera, scene, { alpha: targetAlpha });

  // Guarantee the exact requested unwrapped alpha value on completion.
  camera.alpha = targetAlpha;
}
```

I implemented `spinAround` using the library’s `interpolateArcRotateCamera` transition helper, animating only `alpha` to `startAlpha + 2π * turns` and then forcing the exact final `alpha` after completion. I’m unsure whether the installed library treats `alpha` as an unwrapped numeric value during interpolation and whether camera alpha limits could clamp long rotations; if it wraps angles or enforces tight limits, extra unwrapping/limit handling may be needed.
